-- POS demo data seed for PostgreSQL 17 / EF Core's latest AppDbContext snapshot.
-- Covers 2026-09-01 through 2026-12-31. Run after `dotnet ef database update`.
-- Additive and repeatable: fixed seed UUIDs + natural-key conflict checks; never truncates.
-- Product/SKU catalog rows are embedded from docs/san_pham_kem_ton_kho_380.xlsx.
-- All sale, stock, payment, invoice and loyalty records are linked to real seeded rows.
-- Run after the API bootstrap has created the default owner/store_manager/cashier01 accounts:
--   psql -h localhost -U pos_user -d pos_dev -v ON_ERROR_STOP=1 -f tools/seed_data.sql
--
-- This is a DEVELOPMENT DATASET. Dates in October-December 2026 intentionally include
-- future dates relative to the workstation's current date when this file was authored.

BEGIN;
SET TIME ZONE 'Asia/Ho_Chi_Minh';

DO $seed$
DECLARE
    v_store uuid;
    v_store2 uuid;
    v_owner uuid;
    v_manager uuid;
    v_cashier uuid;
    v_register uuid;
    v_register2 uuid;
    v_normal uuid;
    v_silver uuid;
    v_gold uuid;
    v_vip uuid;
    v_supplier uuid;
    v_customer uuid;
    v_customer2 uuid;
    v_customer3 uuid;
    v_promotion uuid;
    v_voucher uuid;
    v_order uuid;
    v_shift uuid;
    v_sku uuid;
    v_category uuid;
    v_i integer;
    v_j integer;
    v_day date;
    v_month integer;
    v_order_no integer;
    v_sku_code text;
    v_qty numeric(18,3);
    v_price numeric(18,2);
    v_tax numeric(18,2);
    v_subtotal numeric(18,2);
    v_discount numeric(18,2);
    v_total numeric(18,2);
    v_rate numeric(5,4);
    v_paid_at timestamptz;
    v_shift_by_day uuid;
    v_shift_store uuid;
    v_order_count integer := 0;
    v_product_count integer := 0;
    v_json jsonb;
    v_product_row record;
    v_category_row record;
BEGIN
    -- Use the existing chain's primary store when it exists; otherwise create the known demo store.
    SELECT id INTO v_store FROM stores WHERE name = 'Cửa Hàng Trung Tâm' ORDER BY created_at LIMIT 1;
    IF v_store IS NULL THEN
        v_store := '10000000-0000-4000-8000-000000000001';
        INSERT INTO stores(id, name, code, address, phone, timezone, currency_code, tax_code,
                           receipt_header, receipt_footer, is_active, created_at, updated_at)
        VALUES (v_store, 'Cửa Hàng Trung Tâm', 'POS-DEMO-HCM-01',
                '123 Nguyễn Huệ, Quận 1, TP. Hồ Chí Minh', '0901234567',
                'Asia/Ho_Chi_Minh', 'VND', '0101234567',
                'CỬA HÀNG TIỆN LỢI - POS DEMO', 'Cảm ơn quý khách và hẹn gặp lại!', TRUE,
                '2026-08-20 09:00:00+07', '2026-08-20 09:00:00+07')
        ON CONFLICT (id) DO NOTHING;
    END IF;
    SELECT id INTO v_store2 FROM stores WHERE name = 'Chi Nhánh Quận 3' ORDER BY created_at LIMIT 1;
    IF v_store2 IS NULL THEN
        v_store2 := '10000000-0000-4000-8000-000000000002';
        INSERT INTO stores(id, name, code, address, phone, timezone, currency_code, tax_code,
                           receipt_header, receipt_footer, is_active, created_at, updated_at)
        VALUES (v_store2, 'Chi Nhánh Quận 3', 'POS-DEMO-HCM-03',
                '456 Lê Văn Sỹ, Quận 3, TP. Hồ Chí Minh', '0909876543',
                'Asia/Ho_Chi_Minh', 'VND', '0109876543',
                'CỬA HÀNG TIỆN LỢI - CHI NHÁNH Q3', 'Cảm ơn quý khách và hẹn gặp lại!', TRUE,
                '2026-08-20 09:00:00+07', '2026-08-20 09:00:00+07')
        ON CONFLICT (id) DO NOTHING;
    END IF;

    -- Re-resolve IDs after idempotent inserts; existing store codes/names remain authoritative.
    SELECT id INTO v_store FROM stores WHERE name = 'Cửa Hàng Trung Tâm' ORDER BY created_at LIMIT 1;
    SELECT id INTO v_store2 FROM stores WHERE name = 'Chi Nhánh Quận 3' ORDER BY created_at LIMIT 1;

    -- Find or create system roles and operational users. Passwords are valid BCrypt hashes for
    -- the documented Development accounts (Owner@123 / Manager@123 / Cashier@123).
    INSERT INTO roles(id, store_id, name, description, is_system_role, created_at, updated_at)
    VALUES ('20000000-0000-4000-8000-000000000001', NULL, 'Owner', 'Chủ chuỗi - toàn quyền hệ thống', TRUE, '2026-08-20+07', '2026-08-20+07'),
           ('20000000-0000-4000-8000-000000000002', NULL, 'StoreManager', 'Quản lý cửa hàng', TRUE, '2026-08-20+07', '2026-08-20+07'),
           ('20000000-0000-4000-8000-000000000003', NULL, 'Cashier', 'Thu ngân POS', TRUE, '2026-08-20+07', '2026-08-20+07')
    ON CONFLICT DO NOTHING;

    SELECT id INTO v_owner FROM employees WHERE username = 'owner' LIMIT 1;
    SELECT id INTO v_manager FROM employees WHERE username = 'store_manager' LIMIT 1;
    SELECT id INTO v_cashier FROM employees WHERE username = 'cashier01' LIMIT 1;
    IF v_owner IS NULL OR v_manager IS NULL OR v_cashier IS NULL THEN
        RAISE EXCEPTION 'Default employees owner, store_manager, cashier01 are required. Run the Development bootstrap seeder first.';
    END IF;
    UPDATE employees SET phone=COALESCE(phone,'0901234567'),email=COALESCE(email,'owner@pos-demo.local'),
        employment_type=COALESCE(employment_type,'Full-time'),hire_date=COALESCE(hire_date,'2020-01-01'),
        hourly_wage=COALESCE(hourly_wage,0),updated_at='2026-08-20+07' WHERE id=v_owner;
    UPDATE employees SET phone=COALESCE(phone,'0901234568'),email=COALESCE(email,'manager@pos-demo.local'),
        employment_type=COALESCE(employment_type,'Full-time'),hire_date=COALESCE(hire_date,'2022-04-15'),
        hourly_wage=COALESCE(hourly_wage,65000),updated_at='2026-08-20+07' WHERE id=v_manager;
    UPDATE employees SET phone=COALESCE(phone,'0901234569'),email=COALESCE(email,'cashier@pos-demo.local'),
        employment_type=COALESCE(employment_type,'Full-time'),hire_date=COALESCE(hire_date,'2024-06-01'),
        hourly_wage=COALESCE(hourly_wage,35000),updated_at='2026-08-20+07' WHERE id=v_cashier;

    -- Complete current 21-resource / 57-permission RBAC catalog from SystemPermissions.cs.
    INSERT INTO resources(id,code,description)
    SELECT md5('seed-resource:'||x.code)::uuid,x.code,x.description
    FROM (VALUES
      ('stores','Store Management'),('roles','Role & Permission Management'),('employees','Employee Management'),
      ('categories','Category Management'),('products','Product Catalog Management'),('skus','SKU & Pricing Management'),
      ('inventory','Inventory & Stock Management'),('stock_in_vouchers','Stock In Voucher Management'),
      ('stock_takes','Stock Take & Count Management'),('suppliers','Supplier Management'),('shifts','Shift & Cash Reconciliation'),
      ('orders','Order & Sales Management'),('payments','Payment Processing'),('invoices','Invoice & Receipt Management'),
      ('customers','Customer & CRM Management'),('member_tiers','Member Tier Configuration'),('promotions','Promotions Management'),
      ('vouchers','Voucher Management'),('reports','Reports & Analytics'),('config','System & Store Configuration'),
      ('audit_logs','Audit Log Management')
    ) x(code,description)
    ON CONFLICT (code) DO NOTHING;
    INSERT INTO permissions(id,resource_id,action,code,description)
    SELECT md5('seed-permission:'||x.code)::uuid,res.id,x.action,x.code,x.description
    FROM (VALUES
      ('stores','Read','stores:read','View store details and list'),('stores','Manage','stores:manage','Manage stores'),
      ('roles','Manage','roles:manage','Manage roles and permissions'),
      ('employees','Read','employees:read','View employee profiles'),('employees','Manage','employees:manage','Manage employee accounts'),('employees','LoginHistory','employees:login_history','View employee login history'),
      ('categories','Read','categories:read','View categories'),('categories','Manage','categories:manage','Manage categories'),
      ('products','Read','products:read','View product catalog'),('products','Manage','products:manage','Manage product catalog'),('products','Import','products:import','Import products from Excel'),
      ('skus','Read','skus:read','View SKUs and prices'),('skus','Manage','skus:manage','Manage SKUs and unit conversions'),('skus','PriceOverride','skus:price_override','Configure price lists'),
      ('inventory','Read','inventory:read','View stock and alerts'),('inventory','Dispose','inventory:dispose','Dispose stock'),
      ('stock_in_vouchers','Read','stock_in_vouchers:read','View receiving vouchers'),('stock_in_vouchers','Manage','stock_in_vouchers:manage','Manage receiving vouchers'),('stock_in_vouchers','Complete','stock_in_vouchers:complete','Complete stock receipts'),
      ('stock_takes','Manage','stock_takes:manage','Create and edit stock takes'),('stock_takes','Approve','stock_takes:approve','Approve stock takes'),
      ('suppliers','Read','suppliers:read','View suppliers'),('suppliers','Manage','suppliers:manage','Manage suppliers'),('suppliers','Pay','suppliers:pay','Record supplier payments'),
      ('shifts','ManageOwn','shifts:manage_own','Manage own shifts'),('shifts','Read','shifts:read','View shift history'),('shifts','AuditApprove','shifts:audit_approve','Approve cash audits'),
      ('orders','CreateOwn','orders:create_own','Create own orders'),('orders','ReadOwn','orders:read_own','Read own orders'),('orders','Read','orders:read','Read store orders'),('orders','CancelOwn','orders:cancel_own','Cancel own unpaid orders'),('orders','Cancel','orders:cancel','Cancel orders'),('orders','OverrideDiscount','orders:override_discount','Override order discounts'),('orders','Refund','orders:refund','Refund paid orders'),
      ('payments','CreateOwn','payments:create_own','Create own payments'),('payments','Read','payments:read','Read payments'),
      ('invoices','Read','invoices:read','View and print invoices'),
      ('customers','Read','customers:read','View customers'),('customers','Create','customers:create','Create customers'),('customers','Manage','customers:manage','Manage customer profiles'),('customers','LoyaltyAdjust','customers:loyalty_adjust','Adjust loyalty points'),
      ('member_tiers','Read','member_tiers:read','View member tiers'),('member_tiers','Manage','member_tiers:manage','Manage member tiers'),
      ('promotions','Read','promotions:read','View promotions'),('promotions','Manage','promotions:manage','Manage promotions'),
      ('vouchers','Read','vouchers:read','View vouchers'),('vouchers','ApplyOwn','vouchers:apply_own','Apply voucher at POS'),('vouchers','Manage','vouchers:manage','Manage vouchers'),
      ('reports','DashboardView','reports:dashboard_view','View dashboard'),('reports','RevenueView','reports:revenue_view','View revenue reports'),('reports','InventoryView','reports:inventory_view','View inventory reports'),('reports','ProfitView','reports:profit_view','View profit reports'),('reports','Export','reports:export','Export reports'),
      ('config','Read','config:read','Read configuration'),('config','ManageStore','config:manage_store','Manage store configuration'),('config','ManageGlobal','config:manage_global','Manage global configuration'),
      ('audit_logs','Read','audit_logs:read','View audit logs')
    ) x(resource_code,action,code,description)
    JOIN resources res ON res.code=x.resource_code
    ON CONFLICT (code) DO NOTHING;

    INSERT INTO pos_registers(id, store_id, name, code, is_active, created_at, updated_at)
    VALUES ('30000000-0000-4000-8000-000000000001', v_store, 'Quầy 01', 'POS-01', TRUE, '2026-08-20+07', '2026-08-20+07'),
           ('30000000-0000-4000-8000-000000000002', v_store, 'Quầy 02', 'POS-02', TRUE, '2026-08-20+07', '2026-08-20+07'),
           ('30000000-0000-4000-8000-000000000003', v_store2, 'Quầy 01', 'POS-01', TRUE, '2026-08-20+07', '2026-08-20+07')
    ON CONFLICT (store_id, code) DO NOTHING;
    SELECT id INTO v_register FROM pos_registers WHERE store_id = v_store ORDER BY code LIMIT 1;
    SELECT id INTO v_register2 FROM pos_registers WHERE store_id = v_store ORDER BY code DESC LIMIT 1;

    -- Four loyalty tiers (the same thresholds/rates as the application seeder).
    INSERT INTO member_tiers(id,name,min_spending,point_rate,discount_rate,point_redemption_rate,display_color)
    VALUES ('40000000-0000-4000-8000-000000000001','Normal',0,0.0100,0.0000,1000,'#808080'),
           ('40000000-0000-4000-8000-000000000002','Silver',5000000,0.0150,0.0200,1000,'#C0C0C0'),
           ('40000000-0000-4000-8000-000000000003','Gold',15000000,0.0200,0.0500,1000,'#FFD700'),
           ('40000000-0000-4000-8000-000000000004','VIP',30000000,0.0300,0.1000,1000,'#9400D3')
    ON CONFLICT (name) DO NOTHING;
    SELECT id INTO v_normal FROM member_tiers WHERE name='Normal';
    SELECT id INTO v_silver FROM member_tiers WHERE name='Silver';
    SELECT id INTO v_gold FROM member_tiers WHERE name='Gold';
    SELECT id INTO v_vip FROM member_tiers WHERE name='VIP';

    -- Suppliers and customer master records.
    INSERT INTO suppliers(id,name,tax_code,contact_name,phone,email,address,credit_terms,is_active,created_at)
    VALUES ('50000000-0000-4000-8000-000000000001','Công ty TNHH Phân phối Hàng tiêu dùng Sài Gòn','0312345678','Nguyễn Thanh Tâm','02838220001','sales@sgconsumer.example','Quận Bình Thạnh, TP. Hồ Chí Minh','Thanh toán công nợ 15 ngày',TRUE,'2026-08-25+07'),
           ('50000000-0000-4000-8000-000000000002','Công ty Thực phẩm và Đồ uống Miền Nam','0309876543','Lê Minh Phương','02838220002','donhang@southfood.example','Quận Tân Bình, TP. Hồ Chí Minh','Thanh toán công nợ 30 ngày',TRUE,'2026-08-25+07'),
           ('50000000-0000-4000-8000-000000000003','Nhà phân phối Hóa mỹ phẩm Việt','0311122233','Trần Quốc Huy','02838220003','npp@vietcare.example','TP. Thủ Đức, TP. Hồ Chí Minh','Thanh toán chuyển khoản',TRUE,'2026-08-25+07')
    ON CONFLICT (id) DO NOTHING;
    SELECT id INTO v_supplier FROM suppliers WHERE id='50000000-0000-4000-8000-000000000001';

    INSERT INTO customers(id,member_tier_id,name,phone,email,barcode,total_spending,is_active,created_at)
    VALUES ('60000000-0000-4000-8000-000000000001',v_gold,'Nguyễn Thị Minh Châu','0908000001','chau.nguyen@example.com','CUS00000001',18450000,TRUE,'2026-08-25+07'),
           ('60000000-0000-4000-8000-000000000002',v_silver,'Trần Hoàng Nam','0908000002','nam.tran@example.com','CUS00000002',7450000,TRUE,'2026-08-26+07'),
           ('60000000-0000-4000-8000-000000000003',v_normal,'Lê Ngọc Mai','0908000003','mai.le@example.com','CUS00000003',1250000,TRUE,'2026-08-27+07'),
           ('60000000-0000-4000-8000-000000000004',v_vip,'Phạm Gia Hân','0908000004','han.pham@example.com','CUS00000004',36500000,TRUE,'2026-08-28+07'),
           ('60000000-0000-4000-8000-000000000005',v_normal,'Khách lẻ đăng ký POS','0908000005',NULL,'CUS00000005',0,TRUE,'2026-08-29+07')
    ON CONFLICT (phone) DO NOTHING;
    SELECT id INTO v_customer FROM customers WHERE phone='0908000001';
    SELECT id INTO v_customer2 FROM customers WHERE phone='0908000002';
    SELECT id INTO v_customer3 FROM customers WHERE phone='0908000003';
    INSERT INTO loyalty_accounts(id,customer_id,points_balance,last_updated)
    SELECT md5('seed-loyalty:'||c.id::text)::uuid,c.id,0,'2026-08-25+07'::timestamptz
    FROM customers c WHERE c.phone LIKE '090800000%'
    ON CONFLICT (customer_id) DO NOTHING;

    -- Imported 380-product catalog payload. Each source SKU and its source attributes are kept.
    v_json := $products$
    [{"name":"Lốc 4 hộp sữa tươi tiệt trùng hương dâu Vinamilk 110ml","category":"Sữa các loại","unit":"Gói 4","sku":"10010484G4","barcode":"8934673563321","cost":"17500","price":"21900","tax":"8","opening":"48","minimum":"20","lot":"LOT-SUA-001","expiry":"2027-09-30","brand":"VINAMILK","image":"https://s3-hcmc02.higiocloud.vn/images/2024/11/10010484-20241117103123.jpg","attributes":null},{"name":"Sữa Đặc Có Đường Ông Thọ Đỏ Tuýp 165g","category":"Sữa các loại","unit":"Hộp","sku":"10141113HOP","barcode":"8934673200325","cost":"18000","price":"22500","tax":"8","opening":"96","minimum":"20","lot":"LOT-SUA-002","expiry":"2027-09-30","brand":"VINAMILK","image":"https://s3-hcmc02.higiocloud.vn/images/2022/162427179787510141113-hop-sua-dac-cu-duong-eng-tho-do-tuyp-165g-og.jpg","attributes":null},{"name":"Sữa chua uống Meiji dâu tây vỉ 4 hộp x 100ml","category":"Sữa các loại","unit":"Gói 4","sku":"10638796G4","barcode":"8850329536238","cost":"31600","price":"39500","tax":"8","opening":"60","minimum":"20","lot":"LOT-SUA-003","expiry":"2027-03-31","brand":"MEIJI","image":"https://s3-hcmc02.higiocloud.vn/images/2022/162428205701810638796-g4-bot-mo-chuyon-dung-cho-bonh-mo-meizan-gui-1kg-og.jpg","attributes":null},{"name":"Lốc 4 chai sữa chua uống có đường Probi Vinamilk 130ml","category":"Sữa các loại","unit":"Gói 4","sku":"10005485G4","barcode":"8934673304528","cost":"30800","price":"38500","tax":"8","opening":"72","minimum":"20","lot":"LOT-SUA-004","expiry":"2027-07-31","brand":"VINAMILK","image":"https://s3-hcmc02.higiocloud.vn/images/2024/07/blockwarp_probi_cd_130ml_0001-shadow-20240717072137.png","attributes":null},{"name":"Lốc 6 chai sữa chua uống đào tiên Fristi 80ml","category":"Sữa các loại","unit":"Gói 6","sku":"10170365G6","barcode":"8934841902839","cost":"20400","price":"25500","tax":"8","opening":"48","minimum":"20","lot":"LOT-SUA-005","expiry":"2027-09-30","brand":"FRISTI","image":"https://s3-hcmc02.higiocloud.vn/images/2026/03/fristi-80-dao-20260330094312.png","