utes":null},{"name":"Bộ lau nhà  SunHouse 360 KS-CL330S","category":"Đồ Dùng Gia Đình","unit":"Bộ","sku":"10250938ZBO","barcode":"8935259812178","cost":"375200","price":"469000","tax":"8","opening":"30","minimum":"8","lot":"LOT-GD-377","expiry":"","brand":"SUNHOUSE","image":"https://s3-hcmc02.higiocloud.vn/images/2022/sunhouse-bo-lau-nha-360-ks-cl330s_28f2c575-074d-4573-9074-8217b3469946-og.jpg","attributes":null},{"name":"Nồi Lock&Lock Stone 2 tay cầm LCA6242D 24cm (Dùng bếp từ)","category":"Đồ Dùng Gia Đình","unit":"Cái","sku":"10025835CAI","barcode":"6944662534944","cost":"393600","price":"492000","tax":"8","opening":"15","minimum":"8","lot":"LOT-GD-378","expiry":"","brand":"LOCK&LOCK","image":"https://s3-hcmc02.higiocloud.vn/images/2022/162428254899210025835-cai-lo-he-og.jpg","attributes":null},{"name":"Khăn lau siêu mềm Viethop-VN02 30x30cm","category":"Đồ Dùng Gia Đình","unit":"Cái","sku":"10232170CAI","barcode":"8938511172829","cost":"15200","price":"19000","tax":"8","opening":"25","minimum":"8","lot":"LOT-GD-379","expiry":"","brand":"VẠN NĂNG","image":"https://s3-hcmc02.higiocloud.vn/images/2022/162427283341810232170-cai-bo-5-dao-làm-bep-eco-imat-kn-5ps-og.jpg","attributes":null},{"name":"Màng bọc thực phẩm PVC 30CMX150M Dao nhựa Winmart Home","category":"Đồ Dùng Gia Đình","unit":"Hộp","sku":"10166023HOP","barcode":"8934954013965","cost":"87200","price":"109000","tax":"8","opening":"40","minimum":"8","lot":"LOT-GD-380","expiry":"","brand":"WMHOME","image":"https://s3-hcmc02.higiocloud.vn/images/2022/8934954013965.jpg","attributes":null}]
    $products$::jsonb;
    IF jsonb_array_length(v_json) <> 380 THEN
        RAISE EXCEPTION 'Embedded catalog must contain exactly 380 rows; found %', jsonb_array_length(v_json);
    END IF;
    -- Category names in the workbook are leaf categories. Insert each distinct category once.
    FOR v_category_row IN SELECT DISTINCT value->>'category' AS category FROM jsonb_array_elements(v_json) ORDER BY 1 LOOP
        v_category := md5('seed-category:'||v_store::text||':'||v_category_row.category)::uuid;
        IF NOT EXISTS (SELECT 1 FROM categories WHERE store_id=v_store AND name=v_category_row.category) THEN
            INSERT INTO categories(id,store_id,parent_id,name,display_order,image_url,is_visible,created_at)
            VALUES(v_category,v_store,NULL,v_category_row.category,0,NULL,TRUE,'2026-08-20+07')
            ON CONFLICT (id) DO NOTHING;
        END IF;
    END LOOP;
    FOR v_product_row IN SELECT value FROM jsonb_array_elements(v_json) LOOP
        -- Preserve pre-existing catalog rows by SKU code. Missing source rows are reconstructed.
        IF NOT EXISTS (SELECT 1 FROM skus WHERE store_id=v_store AND sku_code=v_product_row.value->>'sku') THEN
            v_category := md5('seed-category:'||v_store::text||':'||(v_product_row.value->>'category'))::uuid;
            v_sku := md5('seed-sku:'||v_store::text||':'||(v_product_row.value->>'sku'))::uuid;
            INSERT INTO products(id,store_id,category_id,name,description,brand,base_unit,image_url,status,created_at,updated_at)
            SELECT md5('seed-product:'||v_store::text||':'||(v_product_row.value->>'sku'))::uuid,v_store,
                   c.id,v_product_row.value->>'name',NULL,NULLIF(v_product_row.value->>'brand',''),
                   v_product_row.value->>'unit',NULLIF(v_product_row.value->>'image',''),'Active','2026-08-20+07','2026-08-20+07'
            FROM categories c WHERE c.store_id=v_store AND c.name=v_product_row.value->>'category'
            ON CONFLICT (id) DO NOTHING;
            INSERT INTO skus(id,product_id,store_id,sku_code,barcode,attributes,cost_price,sell_price,tax_rate,is_active,created_at,updated_at)
            VALUES(v_sku,md5('seed-product:'||v_store::text||':'||(v_product_row.value->>'sku'))::uuid,v_store,
                   v_product_row.value->>'sku',v_product_row.value->>'barcode',NULLIF(v_product_row.value->'attributes','null'::jsonb),
                   (v_product_row.value->>'cost')::numeric,(v_product_row.value->>'price')::numeric,(v_product_row.value->>'tax')::numeric,TRUE,
                   '2026-08-20+07','2026-08-20+07')
            ON CONFLICT (store_id,sku_code) DO NOTHING;
        END IF;
    END LOOP;
    SELECT count(*) INTO v_product_count FROM skus WHERE store_id=v_store;
    IF v_product_count < 380 THEN
        RAISE EXCEPTION 'Store % has only % SKUs after catalog import; expected all 380 source products',v_store,v_product_count;
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_json) x
               WHERE NOT EXISTS (SELECT 1 FROM skus s WHERE s.store_id=v_store AND s.sku_code=x.value->>'sku')) THEN
        RAISE EXCEPTION 'At least one of the 380 embedded source SKUs is missing after import';
    END IF;

    -- Use the application permission catalog already installed by the Development bootstrap;
    -- restore the standard role grants idempotently so the relation table is fully represented.
    INSERT INTO role_permissions(id,role_id,permission_id,granted_by,granted_at)
    SELECT md5('seed-role-permission:'||r.id::text||':'||p.id::text)::uuid,r.id,p.id,v_owner,'2026-08-20+07'
    FROM roles r CROSS JOIN permissions p
    WHERE r.store_id IS NULL AND r.name='Owner'
    ON CONFLICT (role_id,permission_id) DO NOTHING;
    INSERT INTO role_permissions(id,role_id,permission_id,granted_by,granted_at)
    SELECT md5('seed-role-permission:'||r.id::text||':'||p.id::text)::uuid,r.id,p.id,v_owner,'2026-08-20+07'
    FROM roles r CROSS JOIN permissions p
    WHERE r.store_id IS NULL AND r.name='StoreManager'
      AND p.code NOT IN ('stores:manage','roles:manage','member_tiers:manage','reports:profit_view','config:manage_global','audit_logs:read')
    ON CONFLICT (role_id,permission_id) DO NOTHING;
    INSERT INTO role_permissions(id,role_id,permission_id,granted_by,granted_at)
    SELECT md5('seed-role-permission:'||r.id::text||':'||p.id::text)::uuid,r.id,p.id,v_owner,'2026-08-20+07'
    FROM roles r CROSS JOIN permissions p
    WHERE r.store_id IS NULL AND r.name='Cashier'
      AND p.code IN ('stores:read','categories:read','products:read','skus:read','inventory:read','shifts:manage_own',
        'orders:create_own','orders:read_own','orders:cancel_own','payments:create_own','payments:read','invoices:read',
        'customers:read','customers:create','customers:manage','member_tiers:read','promotions:read','vouchers:read','vouchers:apply_own','config:read')
    ON CONFLICT (role_id,permission_id) DO NOTHING;

    -- Default units for case/bundle SKUs and customer-group price examples.
    INSERT INTO unit_conversions(id,sku_id,unit_name,conversion_factor,sell_price)
    SELECT md5('seed-conversion:'||s.id::text)::uuid,s.id,'Thùng',12,s.sell_price*12
    FROM skus s JOIN products p ON p.id=s.product_id
    WHERE s.store_id=v_store AND p.base_unit IN ('Chai','Lon','Hộp','Gói')
      AND s.sku_code IN (SELECT value->>'sku' FROM jsonb_array_elements(v_json) WITH ORDINALITY WHERE ordinality % 17=0)
    ON CONFLICT (sku_id,unit_name) DO NOTHING;
    INSERT INTO price_lists(id,store_id,sku_id,price,valid_from,valid_to,customer_group,created_by,created_at)
    SELECT md5('seed-pricelist:'||s.id::text)::uuid,v_store,s.id,round(s.sell_price*0.97,2),
           '2026-11-01+07','2026-11-30 23:59:59+07','Silver',v_manager,'2026-10-28+07'
    FROM skus s WHERE s.store_id=v_store AND s.sku_code IN
      (SELECT value->>'sku' FROM jsonb_array_elements(v_json) WITH ORDINALITY WHERE ordinality % 41=0)
    ON CONFLICT (id) DO NOTHING;

    -- POS shifts, realistic open/close float, assigned by cashier and register.
    FOR v_day IN SELECT d::date FROM generate_series('2026-09-01'::date,'2026-12-31'::date,'1 day') d LOOP
        IF extract(dow FROM v_day) NOT IN (0) THEN
            FOR v_i IN 1..2 LOOP
                v_shift_store := v_store;
                v_shift_by_day := CASE WHEN v_i=1 THEN v_cashier ELSE v_manager END;
                SELECT id INTO v_register FROM pos_registers
                WHERE store_id=v_store AND code=CASE WHEN v_i=1 THEN 'POS-01' ELSE 'POS-02' END;
                IF v_register IS NULL THEN
                    RAISE EXCEPTION 'Missing POS register % for store %',CASE WHEN v_i=1 THEN 'POS-01' ELSE 'POS-02' END,v_store;
                END IF;
                v_shift := md5('seed-shift:'||v_day::text||':'||v_i::text)::uuid;
                INSERT INTO shifts(id,store_id,register_id,employee_id,opening_cash,closing_cash,actual_cash,status,note,opened_at,closed_at)
                VALUES(v_shift,v_shift_store,v_register,v_shift_by_day,1000000,
                       1000000+((extract(doy from v_day)::int*17321+v_i*9073)%1800000),
                       1000000+((extract(doy from v_day)::int*17321+v_i*9073)%1800000)+((extract(doy from v_day)::int%5)-2)*10000,
                       'Closed',CASE WHEN extract(dow from v_day)=6 THEN 'Ca cuối tuần' ELSE 'Đối soát cuối ca' END,
                       (v_day+time '07:00') AT TIME ZONE 'Asia/Ho_Chi_Minh',
                       (v_day+time '15:00') AT TIME ZONE 'Asia/Ho_Chi_Minh')
                ON CONFLICT (id) DO NOTHING;
            END LOOP;
        END IF;
    END LOOP;

    -- Monthly promotions and matching vouchers.
    FOR v_month IN 9..12 LOOP
        v_promotion := md5('seed-promotion:2026:'||v_month::text)::uuid;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(v_promotion,v_store,
               CASE v_month WHEN 9 THEN 'Tựu trường - ưu đãi đồ uống' WHEN 10 THEN 'Tháng 10 - chăm sóc gia đình' WHEN 11 THEN 'Ngày hội thành viên' ELSE 'Lễ hội cuối năm' END,
               'CartPercent',5,150000,30000,NULL,50,FALSE,FALSE,'All','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',v_manager,
               make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
        v_voucher := md5('seed-voucher:2026:'||v_month::text)::uuid;
        INSERT INTO vouchers(id,promotion_id,code,max_uses,used_count,per_customer_limit,is_active,expires_at)
        VALUES(v_voucher,v_promotion,'THANG'||v_month||'2026',1000,0,2,TRUE,
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh')
        ON CONFLICT (code) DO NOTHING;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(md5('seed-product-promotion:2026:'||v_month::text)::uuid,v_store,
               'Ưu đãi nhóm hàng tháng '||v_month,'PercentSku',5,0,30000,NULL,20,TRUE,FALSE,'Category','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',
               v_manager,make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
    END LOOP;

    -- Category-targeted campaigns create explicit target relations.
    INSERT INTO promotion_targets(id,promotion_id,category_id,sku_id)
    SELECT md5('seed-promotion-target:'||pr.id::text||':'||c.id::text)::uuid,pr.id,c.id,NULL
    FROM promotions pr JOIN categories c ON c.store_id=pr.store_id
    WHERE pr.id IN (SELECT md5('seed-product-promotion:2026:'||m::text)::uuid FROM generate_series(9,12) m)
      AND c.id=(SELECT c2.id FROM categories c2 WHERE c2.store_id=pr.store_id ORDER BY c2.id LIMIT 1)
    ON CONFLICT (id) DO NOTHING;

    -- Stock receipt cycle: every 2 weeks; 12-18 distinct SKUs per voucher.
    INSERT INTO stock_entries(id,store_id,sku_id,qty_on_hand,min_stock,average_cost,last_updated)
    SELECT md5('seed-stock-entry:'||v_store::text||':'||s.id::text)::uuid,v_store,s.id,
           COALESCE((x.value->>'opening')::numeric,24),COALESCE((x.value->>'minimum')::numeric,5),s.cost_price,'2026-09-01+07'
    FROM skus s JOIN jsonb_array_elements(v_json) x(value) ON x.value->>'sku'=s.sku_code
    WHERE s.store_id=v_store
    ON CONFLICT (store_id,sku_id) DO NOTHING;
    INSERT INTO stock_batches(id,store_id,sku_id,batch_no,qty,expiry_date,received_at)
    SELECT md5('seed-stock-batch:'||v_store::text||':'||s.id::text)::uuid,v_store,s.id,
           COALESCE(NULLIF(x.value->>'lot',''), 'OPEN-'||s.sku_code),COALESCE((x.value->>'opening')::numeric,24),
           NULLIF(x.value->>'expiry','')::date,'2026-09-01+07'
    FROM skus s JOIN jsonb_array_elements(v_json) x(value) ON x.value->>'sku'=s.sku_code
    WHERE s.store_id=v_store
    ON CONFLICT (store_id,sku_id,batch_no) DO NOTHING;
    INSERT INTO stock_transactions(id,store_id,sku_id,type,qty,unit_cost,order_id,stock_in_voucher_id,note,created_by,created_at)
    SELECT md5('seed-initial-stock:'||s.id::text)::uuid,v_store,s.id,'StockIn',(x.value->>'opening')::numeric,
           s.cost_price,NULL,NULL,'Seed opening balance from 380-product source workbook',v_manager,'2026-09-01+07'
    FROM skus s JOIN jsonb_array_elements(v_json) x(value) ON x.value->>'sku'=s.sku_code
    WHERE s.store_id=v_store AND (x.value->>'opening')::numeric>0
    ON CONFLICT (id) DO NOTHING;

    FOR v_i IN 0..8 LOOP
        v_day := date '2026-09-01' + v_i*14;
        v_order := md5('seed-stock-voucher:'||v_i::text)::uuid;
        INSERT INTO stock_in_vouchers(id,store_id,supplier_id,total_amount,status,note,created_by,created_at)
        VALUES(v_order,v_store,v_supplier,0,'Completed','Nhập hàng định kỳ - tuần '||to_char(v_day,'IW'),v_manager,(v_day+time '06:30') AT TIME ZONE 'Asia/Ho_Chi_Minh')
        ON CONFLICT (id) DO NOTHING;
        FOR v_product_row IN SELECT s.id sku_id,s.cost_price,COALESCE((x.value->>'opening')::numeric,24) opening,s.sku_code
                 FROM skus s JOIN jsonb_array_elements(v_json) WITH ORDINALITY x(value,ord)
                   ON x.value->>'sku'=s.sku_code
                 WHERE s.store_id=v_store AND (x.ord+v_i)%23=0 LIMIT 18 LOOP
            v_qty := 12 + ((v_i*7+length(v_product_row.sku_code))%25);
            INSERT INTO stock_in_voucher_items(id,voucher_id,sku_id,qty,unit_price,total_price,batch_no,expiry_date)
            VALUES(md5('seed-stock-voucher-item:'||v_i::text||':'||v_product_row.sku_id::text)::uuid,v_order,v_product_row.sku_id,v_qty,v_product_row.cost_price,v_qty*v_product_row.cost_price,
                   'RCV-'||to_char(v_day,'YYMMDD')||'-'||right(v_product_row.sku_code,8),NULL)
            ON CONFLICT (id) DO NOTHING;
            INSERT INTO stock_batches(id,store_id,sku_id,batch_no,qty,expiry_date,received_at)
            VALUES(md5('seed-receipt-batch:'||v_i::text||':'||v_product_row.sku_id::text)::uuid,v_store,v_product_row.sku_id,
                   'RCV-'||to_char(v_day,'YYMMDD')||'-'||right(v_product_row.sku_code,8),v_qty,NULL,(v_day+time '06:30') AT TIME ZONE 'Asia/Ho_Chi_Minh')
            ON CONFLICT (store_id,sku_id,batch_no) DO NOTHING;
            INSERT INTO stock_transactions(id,store_id,sku_id,type,qty,unit_cost,order_id,stock_in_voucher_id,note,created_by,created_at)
            VALUES(md5('seed-stock-in-tx:'||v_i::text||':'||v_product_row.sku_id::text)::uuid,v_store,v_product_row.sku_id,'StockIn',v_qty,v_product_row.cost_price,NULL,v_order,'Seed receipt against completed stock-in voucher',v_manager,(v_day+time '06:45') AT TIME ZONE 'Asia/Ho_Chi_Minh')
            ON CONFLICT (id) DO NOTHING;
            UPDATE stock_entries SET
                average_cost=CASE WHEN qty_on_hand+v_qty>0 THEN round((qty_on_hand*average_cost+v_qty*v_product_row.cost_price)/(qty_on_hand+v_qty),2) ELSE v_product_row.cost_price END,
                qty_on_hand=qty_on_hand+v_qty,last_updated=(v_day+time '06:45') AT TIME ZONE 'Asia/Ho_Chi_Minh'
            WHERE store_id=v_store AND sku_id=v_product_row.sku_id;
        END LOOP;
        UPDATE stock_in_vouchers v SET total_amount=COALESCE((SELECT sum(total_price) FROM stock_in_voucher_items i WHERE i.voucher_id=v.id),0)
        WHERE v.id=v_order;
        IF v_i%2=0 THEN
            INSERT INTO supplier_payments(id,supplier_id,voucher_id,amount,method,paid_at,created_by,note)
            SELECT md5('seed-supplier-payment:'||v_i::text)::uuid,v_supplier,v_order,v.total_amount*0.6,
                   CASE WHEN v_i%4=0 THEN 'BankTransfer' ELSE 'Cash' END,
                   v.created_at+interval '2 days',v_manager,'Thanh toán một phần; phần còn lại theo kỳ hạn'
            FROM stock_in_vouchers v WHERE v.id=v_order AND v.total_amount>0
            ON CONFLICT (id) DO NOTHING;
        END IF;
    END LOOP;

    -- Customer invoices, payments, sale-out ledger and points. 16 orders/day, 6 days/week.
    -- Item quantities are constrained to imported opening stock; use products with ample stock.
    FOR v_day IN SELECT d::date FROM generate_series('2026-09-01'::date,'2026-12-31'::date,'1 day') d LOOP
        IF extract(dow FROM v_day) <> 0 THEN
            v_month := extract(month from v_day)::int;
            FOR v_order_no IN 1..12 LOOP
                v_shift := md5('seed-shift:'||v_day::text||':'||CASE WHEN v_order_no%2=0 THEN '1' ELSE '2' END)::uuid;
                v_shift_by_day := CASE WHEN v_order_no%3=0 THEN v_manager ELSE v_cashier END;
                v_order := md5('seed-order:'||to_char(v_day,'YYYYMMDD')||':'||lpad(v_order_no::text,2,'0'))::uuid;
                IF EXISTS (SELECT 1 FROM orders WHERE id=v_order) THEN CONTINUE; END IF;
                v_customer := CASE v_order_no%5 WHEN 0 THEN NULL WHEN 1 THEN (SELECT id FROM customers WHERE phone='0908000001') WHEN 2 THEN (SELECT id FROM customers WHERE phone='0908000002') WHEN 3 THEN (SELECT id FROM customers WHERE phone='0908000003') ELSE (SELECT id FROM customers WHERE phone='0908000004') END;
                v_subtotal := 0; v_discount := 0; v_tax := 0;
                INSERT INTO orders(id,store_id,shift_id,customer_id,status,currency_code,subtotal,discount_total,tax_total,grand_total,note,applied_voucher_id,applied_voucher_code,created_by,created_at,paid_at,cancel_reason)
                VALUES(v_order,v_store,v_shift,v_customer,'Draft','VND',0,0,0,0,NULL,NULL,NULL,v_shift_by_day,
                       ((v_day+time '08:00') AT TIME ZONE 'Asia/Ho_Chi_Minh')+make_interval(mins=>v_order_no*31),NULL,NULL)
                ON CONFLICT (id) DO NOTHING;
                FOR v_j IN 1..(2+(v_order_no%3)) LOOP
                    v_qty := 1+((v_order_no+v_j+extract(doy from v_day)::int)%3);
                    SELECT s.id,s.sku_code,s.sell_price,s.tax_rate INTO v_sku,v_sku_code,v_price,v_tax
                    FROM skus s JOIN jsonb_array_elements(v_json) WITH ORDINALITY x(value,ord) ON x.value->>'sku'=s.sku_code
                    WHERE s.store_id=v_store AND s.is_active
                      AND EXISTS (SELECT 1 FROM stock_entries se WHERE se.store_id=v_store AND se.sku_id=s.id AND se.qty_on_hand>=v_qty)
                      AND NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id=v_order AND oi.sku_id=s.id)
                    ORDER BY mod(x.ord-(((v_order_no*13+v_j*29+extract(doy from v_day)::int*7)%380)+1)+380,380)
                    LIMIT 1;
                    IF v_sku IS NULL THEN CONTINUE; END IF;
                    v_tax := round((v_price*v_qty)*(v_tax/100),2);
                    INSERT INTO order_items(id,order_id,sku_id,qty,unit_price,discount_amount,tax_amount,line_total)
                    VALUES(md5('seed-order-item:'||v_order::text||':'||v_j::text)::uuid,v_order,v_sku,v_qty,v_price,0,v_tax,v_price*v_qty+v_tax)
                    ON CONFLICT (id) DO NOTHING;
                    UPDATE stock_entries SET qty_on_hand=qty_on_hand-v_qty,
                        last_updated=((v_day+time '08:00') AT TIME ZONE 'Asia/Ho_Chi_Minh')+make_interval(mins=>v_order_no*31+4)
                    WHERE store_id=v_store AND sku_id=v_sku;
                    v_subtotal := v_subtotal+v_price*v_qty;
                END LOOP;
                IF v_subtotal=0 THEN CONTINUE; END IF;
                v_discount := CASE WHEN v_order_no%4=0 AND v_subtotal>=150000 THEN least(30000,round(v_subtotal*0.05,2)) ELSE 0 END;
                SELECT COALESCE(sum(tax_amount),0) INTO v_tax FROM order_items WHERE order_id=v_order;
                v_total := round(v_subtotal-v_discount+v_tax,2);
                v_paid_at := ((v_day+time '08:00') AT TIME ZONE 'Asia/Ho_Chi_Minh')+make_interval(mins=>v_order_no*31+4);
                v_voucher := CASE WHEN v_discount>0 THEN md5('seed-voucher:2026:'||v_month::text)::uuid ELSE NULL END;
                UPDATE orders SET status='Paid',subtotal=v_subtotal,discount_total=v_discount,tax_total=v_tax,grand_total=v_total,
                                  applied_voucher_id=v_voucher,applied_voucher_code=CASE WHEN v_voucher IS NULL THEN NULL ELSE 'THANG'||v_month||'2026' END,paid_at=v_paid_at
                WHERE id=v_order;
                IF v_discount>0 AND v_voucher IS NOT NULL THEN
                    INSERT INTO order_discounts(id,order_id,promotion_id,voucher_id,discount_amount,description,applied_at)
                    VALUES(md5('seed-order-discount:'||v_order::text)::uuid,v_order,md5('seed-promotion:2026:'||v_month::text)::uuid,v_voucher,v_discount,'Ưu đãi hóa đơn tháng '||v_month,v_paid_at)
                    ON CONFLICT (id) DO NOTHING;
                    INSERT INTO voucher_usages(id,voucher_id,customer_id,order_id,used_at)
                    SELECT md5('seed-voucher-use:'||v_order::text)::uuid,v_voucher,v_customer,v_order,v_paid_at
                    WHERE v_customer IS NOT NULL
                    ON CONFLICT (voucher_id,order_id) DO NOTHING;
                    UPDATE vouchers SET used_count=(SELECT count(*) FROM voucher_usages WHERE voucher_id=v_voucher) WHERE id=v_voucher;
                END IF;
                INSERT INTO payments(id,order_id,method,amount,change_amount,transaction_ref,merchant_reference,status,gateway_response_json,paid_at)
                VALUES(md5('seed-payment:'||v_order::text)::uuid,v_order,
                       CASE v_order_no%5 WHEN 0 THEN 'Card' WHEN 1 THEN 'VietQR' WHEN 2 THEN 'MoMo' ELSE 'Cash' END,
                       CASE WHEN v_order_no%5=3 THEN v_total+20000 ELSE v_total END,
                       CASE WHEN v_order_no%5=3 THEN 20000 ELSE NULL END,
                       CASE WHEN v_order_no%5 IN (0,1,2) THEN 'DEMO-'||to_char(v_day,'YYYYMMDD')||'-'||lpad(v_order_no::text,3,'0') ELSE NULL END,
                       CASE WHEN v_order_no%5 IN (1,2) THEN 'MREF'||to_char(v_day,'YYMMDD')||lpad(v_order_no::text,4,'0') ELSE NULL END,
                       'Success',CASE WHEN v_order_no%5 IN (1,2) THEN '{"seed":true,"gateway":"sandbox"}'::jsonb ELSE NULL END,v_paid_at)
                ON CONFLICT (id) DO NOTHING;
                INSERT INTO invoices(id,order_id,invoice_no,buyer_name,buyer_tax_code,buyer_address,total_before_tax,tax_amount,grand_total,issued_at)
                VALUES(md5('seed-invoice:'||v_order::text)::uuid,v_order,'HD-'||(SELECT code FROM stores WHERE id=v_store)||'-'||to_char(v_day,'YYYYMMDD')||'-'||lpad(v_order_no::text,6,'0'),
                       CASE WHEN v_customer IS NOT NULL THEN (SELECT name FROM customers WHERE id=v_customer) ELSE NULL END,NULL,NULL,
                       v_subtotal-v_discount,v_tax,v_total,v_paid_at)
                ON CONFLICT (order_id) DO NOTHING;
                INSERT INTO invoice_sequences(store_id,invoice_date,last_value)
                VALUES(v_store,v_day,v_order_no)
                ON CONFLICT (store_id,invoice_date) DO UPDATE SET last_value=GREATEST(invoice_sequences.last_value,EXCLUDED.last_value);
                INSERT INTO stock_transactions(id,store_id,sku_id,type,qty,unit_cost,order_id,stock_in_voucher_id,note,created_by,created_at)
                SELECT md5('seed-sale-tx:'||oi.id::text)::uuid,v_store,oi.sku_id,'SaleOut',oi.qty,s.cost_price,oi.order_id,NULL,'Seed POS sale transaction',v_shift_by_day,v_paid_at
                FROM order_items oi JOIN skus s ON s.id=oi.sku_id WHERE oi.order_id=v_order
                ON CONFLICT (id) DO NOTHING;
                IF v_customer IS NOT NULL THEN
                    UPDATE customers SET total_spending=total_spending+v_total,
                        member_tier_id=CASE WHEN total_spending+v_total>=30000000 THEN v_vip
                                            WHEN total_spending+v_total>=15000000 THEN v_gold
                                            WHEN total_spending+v_total>=5000000 THEN v_silver ELSE v_normal END
                    WHERE id=v_customer;
                    SELECT mt.point_rate INTO v_rate FROM customers c JOIN member_tiers mt ON mt.id=c.member_tier_id WHERE c.id=v_customer;
                    INSERT INTO point_transactions(id,customer_id,order_id,type,points,note,created_at)
                    VALUES(md5('seed-points:'||v_order::text)::uuid,v_customer,v_order,'Earn',round(v_total*COALESCE(v_rate,0.01),0),'Tích điểm theo hạng thành viên sau hóa đơn POS',v_paid_at)
                    ON CONFLICT (id) DO NOTHING;
                    UPDATE loyalty_accounts SET points_balance=COALESCE((SELECT sum(CASE WHEN type='Redeem' THEN -points ELSE points END) FROM point_transactions WHERE customer_id=v_customer),0),last_updated=v_paid_at
                    WHERE customer_id=v_customer;
                END IF;
                v_order_count := v_order_count+1;
            END LOOP;
        END IF;
    END LOOP;

    -- One split tender example: redeem 10 loyalty points (10,000 VND) and settle the balance in cash.
    v_order := md5('seed-order:20261219:04')::uuid;
    IF EXISTS (SELECT 1 FROM orders WHERE id=v_order)
       AND NOT EXISTS (SELECT 1 FROM payments WHERE id=md5('seed-split-points-payment:'||v_order::text)::uuid) THEN
        UPDATE payments SET amount=amount-10000
        WHERE id=md5('seed-payment:'||v_order::text)::uuid AND amount>10000;
        INSERT INTO payments(id,order_id,method,amount,change_amount,transaction_ref,merchant_reference,status,gateway_response_json,paid_at)
        SELECT md5('seed-split-points-payment:'||o.id::text)::uuid,o.id,'Points',10000,NULL,NULL,NULL,'Success',NULL,o.paid_at
        FROM orders o WHERE o.id=v_order AND o.grand_total>10000
        ON CONFLICT (id) DO NOTHING;
        INSERT INTO point_transactions(id,customer_id,order_id,type,points,note,created_at)
        SELECT md5('seed-split-points-ledger:'||o.id::text)::uuid,o.customer_id,o.id,'Redeem',10,
               'Đổi 10 điểm (10.000đ) khi thanh toán tách phương thức',o.paid_at
        FROM orders o WHERE o.id=v_order AND o.customer_id IS NOT NULL
        ON CONFLICT (id) DO NOTHING;
        UPDATE loyalty_accounts la SET points_balance=COALESCE((SELECT sum(CASE WHEN pt.type='Redeem' THEN -pt.points ELSE pt.points END)
                FROM point_transactions pt WHERE pt.customer_id=la.customer_id),0),last_updated='2026-12-31 23:59:59+07'
        WHERE la.customer_id=(SELECT customer_id FROM orders WHERE id=v_order);
    END IF;

    -- Representative non-paid lifecycle states and gateway outcomes; no invoice or stock-out
    -- is written for unpaid/cancelled orders, matching the OrderPaid side-effect rules.
    FOR v_i IN 1..4 LOOP
        v_day := make_date(2026,8+v_i,16);
        v_order := md5('seed-edge-order:'||v_i::text)::uuid;
        v_shift := md5('seed-shift:'||v_day::text||':1')::uuid;
        SELECT id,sku_code,sell_price,tax_rate INTO v_sku,v_sku_code,v_price,v_tax
        FROM skus WHERE store_id=v_store ORDER BY sku_code OFFSET (v_i*31) LIMIT 1;
        INSERT INTO orders(id,store_id,shift_id,customer_id,status,currency_code,subtotal,discount_total,tax_total,grand_total,note,created_by,created_at,paid_at,cancel_reason)
        VALUES(v_order,v_store,v_shift,CASE WHEN v_i=1 THEN v_customer ELSE NULL END,
               CASE v_i WHEN 1 THEN 'Cancelled' WHEN 2 THEN 'Confirmed' WHEN 3 THEN 'Confirmed' ELSE 'Draft' END,
               'VND',CASE WHEN v_i=4 THEN 0 ELSE v_price END,0,
               CASE WHEN v_i=4 THEN 0 ELSE round(v_price*v_tax/100,2) END,
               CASE WHEN v_i=4 THEN 0 ELSE v_price+round(v_price*v_tax/100,2) END,
               CASE v_i WHEN 1 THEN 'Khách đổi ý trước thanh toán' WHEN 2 THEN 'Chờ khách hoàn tất VietQR' WHEN 3 THEN 'Giao dịch thẻ bị từ chối' ELSE 'Giỏ hàng nháp chưa checkout' END,
               v_cashier,(v_day+time '19:00') AT TIME ZONE 'Asia/Ho_Chi_Minh',NULL,
               CASE WHEN v_i=1 THEN 'Khách yêu cầu hủy trước khi thanh toán' ELSE NULL END)
        ON CONFLICT (id) DO NOTHING;
        IF v_i<4 THEN
            INSERT INTO order_items(id,order_id,sku_id,qty,unit_price,discount_amount,tax_amount,line_total)
            VALUES(md5('seed-edge-item:'||v_i::text)::uuid,v_order,v_sku,1,v_price,0,round(v_price*v_tax/100,2),v_price+round(v_price*v_tax/100,2))
            ON CONFLICT (id) DO NOTHING;
        END IF;
        IF v_i IN (2,3) THEN
            INSERT INTO payments(id,order_id,method,amount,change_amount,transaction_ref,merchant_reference,status,gateway_response_json,paid_at)
            VALUES(md5('seed-edge-payment:'||v_i::text)::uuid,v_order,CASE WHEN v_i=2 THEN 'VietQR' ELSE 'Card' END,
                   v_price+round(v_price*v_tax/100,2),NULL,
                   CASE WHEN v_i=3 THEN 'DEMO-DECLINED-20261016' ELSE NULL END,
                   CASE WHEN v_i=2 THEN 'MREF-PENDING-20261116' ELSE NULL END,
                   CASE WHEN v_i=2 THEN 'Pending' ELSE 'Failed' END,
                   CASE WHEN v_i=2 THEN '{"seed":true,"state":"awaiting_webhook"}'::jsonb ELSE '{"seed":true,"decline_code":"insufficient_funds"}'::jsonb END,
                   NULL)
            ON CONFLICT (id) DO NOTHING;
        END IF;
    END LOOP;
    v_day := date '2026-12-21';
    v_order := md5('seed-edge-order:qr-timeout')::uuid;
    v_shift := md5('seed-shift:'||v_day::text||':1')::uuid;
    SELECT id,sku_code,sell_price,tax_rate INTO v_sku,v_sku_code,v_price,v_tax
    FROM skus WHERE store_id=v_store ORDER BY sku_code OFFSET 73 LIMIT 1;
    INSERT INTO orders(id,store_id,shift_id,customer_id,status,currency_code,subtotal,discount_total,tax_total,grand_total,note,created_by,created_at,paid_at,cancel_reason)
    VALUES(v_order,v_store,v_shift,NULL,'Confirmed','VND',v_price,0,round(v_price*v_tax/100,2),v_price+round(v_price*v_tax/100,2),
           'Đơn QR hết thời gian chờ; chưa ghi nhận doanh thu',v_cashier,'2026-12-21 20:10+07',NULL,NULL)
    ON CONFLICT (id) DO NOTHING;
    INSERT INTO order_items(id,order_id,sku_id,qty,unit_price,discount_amount,tax_amount,line_total)
    VALUES(md5('seed-edge-item:qr-timeout')::uuid,v_order,v_sku,1,v_price,0,round(v_price*v_tax/100,2),v_price+round(v_price*v_tax/100,2))
    ON CONFLICT (id) DO NOTHING;
    INSERT INTO payments(id,order_id,method,amount,change_amount,transaction_ref,merchant_reference,status,gateway_response_json,paid_at)
    VALUES(md5('seed-edge-payment:qr-timeout')::uuid,v_order,'VietQR',v_price+round(v_price*v_tax/100,2),NULL,NULL,
           'MREF-TIMEOUT-20261221','Timeout','{"seed":true,"state":"expired"}'::jsonb,NULL)
    ON CONFLICT (id) DO NOTHING;

    -- Reconcile the imported opening balance, completed receipts and paid sale-out ledger.
    UPDATE stock_entries se SET qty_on_hand=GREATEST(0,
        COALESCE((SELECT sum(st.qty) FROM stock_transactions st
                    WHERE st.store_id=v_store AND st.sku_id=se.sku_id AND st.type='StockIn'
                      AND (st.note='Seed receipt against completed stock-in voucher'
                           OR st.note='Seed opening balance from 380-product source workbook')),0)
        - COALESCE((SELECT sum(st.qty) FROM stock_transactions st
                    WHERE st.store_id=v_store AND st.sku_id=se.sku_id AND st.type='SaleOut'
                      AND st.note IN ('Seed POS sale transaction','Seed promotion scenario sale')),0)),
        average_cost=(x.value->>'cost')::numeric,last_updated='2026-12-31 23:59:59+07'
    FROM skus s JOIN jsonb_array_elements(v_json) x(value) ON x.value->>'sku'=s.sku_code
    WHERE s.id=se.sku_id AND se.store_id=v_store;

    -- Consume inventory batches oldest-first so remaining batch quantities reconcile with stock.
    UPDATE stock_batches sb SET qty=(x.value->>'opening')::numeric
    FROM skus s JOIN jsonb_array_elements(v_json) x(value) ON x.value->>'sku'=s.sku_code
    WHERE sb.id=md5('seed-stock-batch:'||v_store::text||':'||s.id::text)::uuid AND sb.store_id=v_store AND sb.sku_id=s.id;
    UPDATE stock_batches sb SET qty=i.qty
    FROM generate_series(0,8) n
    JOIN stock_in_voucher_items i ON i.id=md5('seed-stock-voucher-item:'||n::text||':'||i.sku_id::text)::uuid
    WHERE sb.id=md5('seed-receipt-batch:'||n::text||':'||i.sku_id::text)::uuid AND sb.store_id=v_store AND sb.sku_id=i.sku_id;
    WITH seed_batches AS (
        SELECT sb.id,sb.sku_id,sb.qty AS original_qty,sb.received_at,sb.batch_no,
               (sb.id=md5('seed-stock-batch:'||v_store::text||':'||sb.sku_id::text)::uuid) AS opening_batch,
               COALESCE(sum(sb.qty) FILTER (WHERE sb.id<>md5('seed-stock-batch:'||v_store::text||':'||sb.sku_id::text)::uuid)
                   OVER (PARTITION BY sb.sku_id ORDER BY sb.received_at,sb.batch_no ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS prior_receipts
        FROM stock_batches sb
        WHERE sb.store_id=v_store AND (sb.id=md5('seed-stock-batch:'||v_store::text||':'||sb.sku_id::text)::uuid
             OR sb.id IN (SELECT md5('seed-receipt-batch:'||n::text||':'||s.id::text)::uuid FROM generate_series(0,8) n CROSS JOIN skus s WHERE s.store_id=v_store))
    ), sales AS (
        SELECT sku_id,sum(qty) sold FROM stock_transactions
        WHERE store_id=v_store AND type='SaleOut' AND note IN ('Seed POS sale transaction','Seed promotion scenario sale') GROUP BY sku_id
    ), opening AS (
        SELECT sku_id,original_qty FROM seed_batches WHERE opening_batch
    )
    UPDATE stock_batches sb SET qty=CASE WHEN b.opening_batch
        THEN GREATEST(0,b.original_qty-COALESCE(s.sold,0))
        ELSE GREATEST(0,b.original_qty-GREATEST(0,COALESCE(s.sold,0)-COALESCE(o.original_qty,0)-b.prior_receipts)) END
    FROM seed_batches b LEFT JOIN sales s ON s.sku_id=b.sku_id LEFT JOIN opening o ON o.sku_id=b.sku_id
    WHERE sb.id=b.id;

    -- Stock counts with approved/pending/draft examples and computed item deltas.
    FOR v_i IN 1..4 LOOP
        v_order := md5('seed-stocktake:'||v_i::text)::uuid;
        v_day := make_date(2026,8+v_i,25);
        INSERT INTO stock_takes(id,store_id,status,created_by,approved_by,note,created_at,approved_at)
        VALUES(v_order,v_store,CASE WHEN v_i=4 THEN 'Draft' WHEN v_i=3 THEN 'Pending' ELSE 'Approved' END,
               v_manager,CASE WHEN v_i<=2 THEN v_owner ELSE NULL END,
               'Kiểm kê định kỳ cuối tháng '||extract(month from v_day)::int,
               (v_day+time '18:00') AT TIME ZONE 'Asia/Ho_Chi_Minh',
               CASE WHEN v_i<=2 THEN ((v_day+time '18:45') AT TIME ZONE 'Asia/Ho_Chi_Minh') ELSE NULL END)
        ON CONFLICT (id) DO NOTHING;
        FOR v_product_row IN SELECT s.id sku_id,s.sku_code FROM skus s WHERE s.store_id=v_store ORDER BY s.sku_code LIMIT 20 LOOP
            INSERT INTO stock_take_items(id,take_id,sku_id,system_qty,actual_qty,note)
            SELECT md5('seed-stocktake-item:'||v_i::text||':'||v_product_row.sku_id::text)::uuid,v_order,v_product_row.sku_id,
                   se.qty_on_hand,se.qty_on_hand+CASE WHEN v_product_row.sku_code ~ '[13579]$' THEN 1 ELSE 0 END,
                   CASE WHEN v_product_row.sku_code ~ '[13579]$' THEN 'Bù thiếu 1 đơn vị sau kiểm đếm' ELSE NULL END
            FROM stock_entries se WHERE se.store_id=v_store AND se.sku_id=v_product_row.sku_id
            ON CONFLICT (id) DO NOTHING;
        END LOOP;
    END LOOP;

    -- Customer support/chat sample, valid conversation/message relations.
    INSERT INTO chat_conversations(id,store_id,customer_id,session_id,message_count,started_at,ended_at)
    VALUES('70000000-0000-4000-8000-000000000001',v_store,v_customer,'demo-session-customer-01',2,'2026-10-12 10:05+07','2026-10-12 10:07+07'),
          ('70000000-0000-4000-8000-000000000002',v_store,v_customer2,'demo-session-customer-02',2,'2026-11-08 16:30+07','2026-11-08 16:32+07')
    ON CONFLICT (id) DO NOTHING;
    INSERT INTO chat_messages(id,conversation_id,sender,content,created_at)
    VALUES('71000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','Customer','Cửa hàng còn sữa tươi Vinamilk không?', '2026-10-12 10:05+07'),
          ('71000000-0000-4000-8000-000000000002','70000000-0000-4000-8000-000000000001','Bot','Dạ còn hàng ạ. Anh/chị có thể xem tồn kho tại quầy hoặc đặt giữ hàng.', '2026-10-12 10:06+07'),
          ('71000000-0000-4000-8000-000000000003','70000000-0000-4000-8000-000000000002','Customer','Chương trình thành viên tháng này áp dụng thế nào?', '2026-11-08 16:30+07'),
          ('71000000-0000-4000-8000-000000000004','70000000-0000-4000-8000-000000000002','Bot','Hóa đơn từ 150.000đ được giảm 5% theo ưu đãi tháng 11.', '2026-11-08 16:31+07')
    ON CONFLICT (id) DO NOTHING;

    -- System configuration, translations and audit history are global/store scoped as designed.
    INSERT INTO system_configs(id,store_id,key,value,updated_at)
    VALUES('72000000-0000-4000-8000-000000000001',v_store,'pos.receipt.paper_width','80','2026-08-20+07'),
          ('72000000-0000-4000-8000-000000000002',v_store,'pos.inventory.low_stock_alert','true','2026-08-20+07'),
          ('72000000-0000-4000-8000-000000000003',NULL,'loyalty.point_redemption_rate','1000','2026-08-20+07')
    ON CONFLICT DO NOTHING;
    INSERT INTO translations(id,language_code,key,value,updated_at)
    VALUES('73000000-0000-4000-8000-000000000001','vi','order.paid','Đã thanh toán','2026-08-20+07'),
          ('73000000-0000-4000-8000-000000000002','vi','order.cancelled','Đã hủy','2026-08-20+07'),
          ('73000000-0000-4000-8000-000000000003','en','order.paid','Paid','2026-08-20+07'),
          ('73000000-0000-4000-8000-000000000004','en','order.cancelled','Cancelled','2026-08-20+07')
    ON CONFLICT (language_code,key) DO NOTHING;
    INSERT INTO audit_logs(id,store_id,employee_id,action,entity_type,entity_id,description,ip_address,created_at)
    VALUES('74000000-0000-4000-8000-000000000001',v_store,v_manager,'StockInCompleted','StockInVoucher',md5('seed-stock-voucher:0')::uuid,'Hoàn tất nhận hàng theo lịch nhập tháng 9','192.168.1.10','2026-09-01 06:45+07'),
          ('74000000-0000-4000-8000-000000000002',v_store,v_owner,'StockTakeApproved','StockTake',md5('seed-stocktake:1')::uuid,'Duyệt kiểm kê cuối tháng 9','192.168.1.2','2026-09-25 18:45+07')
    ON CONFLICT (id) DO NOTHING;

    -- RefreshTokens has no active demo credentials; seed only revoked/expired audit examples.
    INSERT INTO refresh_tokens(id,employee_id,token_hash,expires_at,revoked_at,created_at)
    VALUES('75000000-0000-4000-8000-000000000001',v_cashier,'seed-revoked-token-hash-cashier-2026',
           '2026-09-01+07','2026-09-01+07','2026-08-31+07'),
          ('75000000-0000-4000-8000-000000000002',v_manager,'seed-revoked-token-hash-manager-2026',
           '2026-10-01+07','2026-10-01+07','2026-09-30+07')
    ON CONFLICT (token_hash) DO NOTHING;

    RAISE NOTICE 'Seed complete: % paid orders, all 380 source SKUs verified, 2026-09-01..2026-12-31.',v_order_count;
END;
$seed$;

-- Complete every PromotionType supported by PromotionEngine and add paid sample orders
-- that exercise item %, fixed item, buy-X-get-Y, fixed-cart, happy-hour and the existing cart-% campaigns.
DO $promotion_seed$
DECLARE
    v_store uuid;
    v_manager uuid;
    v_cashier uuid;
    v_register uuid;
    v_customer uuid;
    v_member_tier uuid;
    v_normal uuid;
    v_silver uuid;
    v_gold uuid;
    v_vip uuid;
    v_sku uuid;
    v_target_sku uuid;
    v_category uuid;
    v_target_category uuid;
    v_promotion uuid;
    v_voucher uuid;
    v_order uuid;
    v_shift uuid;
    v_day date;
    v_month integer;
    v_qty numeric(18,3);
    v_price numeric(18,2);
    v_rate numeric(18,2);
    v_gross numeric(18,2);
    v_discount numeric(18,2);
    v_tax numeric(18,2);
    v_total numeric(18,2);
    v_paid_at timestamptz;
    v_invoice_sequence bigint;
    v_invoice_no text;
    v_campaign_code text;
    v_sample record;
BEGIN
    SELECT id INTO v_store FROM stores WHERE name='Cửa Hàng Trung Tâm' ORDER BY created_at LIMIT 1;
    SELECT id INTO v_manager FROM employees WHERE username='store_manager' LIMIT 1;
    SELECT id INTO v_cashier FROM employees WHERE username='cashier01' LIMIT 1;
    SELECT id INTO v_register FROM pos_registers WHERE store_id=v_store AND code='POS-01' LIMIT 1;
    SELECT id INTO v_normal FROM member_tiers WHERE name='Normal';
    SELECT id INTO v_silver FROM member_tiers WHERE name='Silver';
    SELECT id INTO v_gold FROM member_tiers WHERE name='Gold';
    SELECT id INTO v_vip FROM member_tiers WHERE name='VIP';

    -- Add SKU-fixed, buy-X-get-Y, cart-fixed and happy-hour campaigns each month.
    FOR v_month IN 9..12 LOOP
        SELECT s.id,p.category_id INTO v_sku,v_category
        FROM skus s JOIN products p ON p.id=s.product_id
        JOIN stock_entries se ON se.store_id=s.store_id AND se.sku_id=s.id
        WHERE s.store_id=v_store AND s.is_active AND se.qty_on_hand>=5
          AND EXISTS (SELECT 1 FROM stock_batches b WHERE b.store_id=s.store_id AND b.sku_id=s.id AND b.qty>=5)
        ORDER BY s.sku_code OFFSET ((v_month-9)*3) LIMIT 1;
        IF v_sku IS NULL THEN RAISE EXCEPTION 'No stocked SKU available for promotion scenario'; END IF;

        v_promotion := md5('seed-fixed-sku:2026:'||v_month::text)::uuid;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(v_promotion,v_store,'Giảm 5.000đ mỗi sản phẩm - tháng '||v_month,'FixedSku',5000,0,30000,NULL,45,FALSE,FALSE,'SKU','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',v_manager,
               make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
        INSERT INTO promotion_targets(id,promotion_id,category_id,sku_id)
        VALUES(md5('seed-fixed-target:2026:'||v_month::text)::uuid,v_promotion,NULL,v_sku)
        ON CONFLICT (id) DO NOTHING;

        v_promotion := md5('seed-buyxgety:2026:'||v_month::text)::uuid;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(v_promotion,v_store,'Mua 2 tặng 1 cùng sản phẩm - tháng '||v_month,'BuyXGetY',0,0,200000,
               '{"BuyQuantity":2,"GetQuantity":1,"FreeSkuId":null,"DiscountPercent":100}',60,FALSE,FALSE,'SKU','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',v_manager,
               make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
        INSERT INTO promotion_targets(id,promotion_id,category_id,sku_id)
        VALUES(md5('seed-buyxgety-target:2026:'||v_month::text)::uuid,v_promotion,NULL,v_sku)
        ON CONFLICT (id) DO NOTHING;
        v_campaign_code := 'MUA2TANG1-2026-'||lpad(v_month::text,2,'0');
        INSERT INTO vouchers(id,promotion_id,code,max_uses,used_count,per_customer_limit,is_active,expires_at)
        VALUES(md5('seed-buyxgety-voucher:2026:'||v_month::text)::uuid,v_promotion,v_campaign_code,500,0,2,TRUE,
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh')
        ON CONFLICT (code) DO NOTHING;

        v_promotion := md5('seed-cartfixed:2026:'||v_month::text)::uuid;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(v_promotion,v_store,'Giảm 15.000đ cho đơn từ 100.000đ - tháng '||v_month,'CartFixed',15000,100000,15000,NULL,35,FALSE,FALSE,'All','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',v_manager,
               make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
        v_campaign_code := 'GIAM15K-2026-'||lpad(v_month::text,2,'0');
        INSERT INTO vouchers(id,promotion_id,code,max_uses,used_count,per_customer_limit,is_active,expires_at)
        VALUES(md5('seed-cartfixed-voucher:2026:'||v_month::text)::uuid,v_promotion,v_campaign_code,500,0,2,TRUE,
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh')
        ON CONFLICT (code) DO NOTHING;

        v_promotion := md5('seed-happyhour:2026:'||v_month::text)::uuid;
        INSERT INTO promotions(id,store_id,name,type,value,min_order_amount,max_discount_amount,conditions_json,priority,is_stackable,is_exclusive,applies_to,status,valid_from,valid_to,created_by,created_at)
        VALUES(v_promotion,v_store,'Happy Hour 14:00-17:00 giảm 10% - tháng '||v_month,'HappyHour',10,0,50000,
               '{"StartTime":"14:00:00","EndTime":"17:00:00","DaysOfWeek":[1,2,3,4,5,6]}',55,FALSE,FALSE,'Category','Active',
               make_timestamptz(2026,v_month,1,0,0,0,'Asia/Ho_Chi_Minh'),
               (make_date(2026,v_month,1)+interval '1 month - 1 second') AT TIME ZONE 'Asia/Ho_Chi_Minh',v_manager,
               make_timestamptz(2026,v_month,1,8,0,0,'Asia/Ho_Chi_Minh'))
        ON CONFLICT (id) DO NOTHING;
        INSERT INTO promotion_targets(id,promotion_id,category_id,sku_id)
        VALUES(md5('seed-happyhour-target:2026:'||v_month::text)::uuid,v_promotion,v_category,NULL)
        ON CONFLICT (id) DO NOTHING;
    END LOOP;

    -- One paid order for each line/cart promotion family not represented by the 275 cart-percent orders.
    FOR v_sample IN
        SELECT * FROM (VALUES
          ('PercentSku','seed-product-promotion:2026:9',DATE '2026-09-22',1,NULL::text,NULL::text),
          ('FixedSku','seed-fixed-sku:2026:10',DATE '2026-10-20',2,NULL::text,NULL::text),
          ('BuyXGetY','seed-buyxgety:2026:11',DATE '2026-11-20',3,'MUA2TANG1-2026-11','CUS00000001'),
          ('CartFixed','seed-cartfixed:2026:12',DATE '2026-12-22',3,'GIAM15K-2026-12','CUS00000002'),
          ('HappyHour','seed-happyhour:2026:12',DATE '2026-12-23',2,NULL::text,NULL::text)
        ) AS samples(kind,promotion_key,sale_day,quantity,voucher_code,customer_barcode)
    LOOP
        v_order := md5('seed-promotion-example:'||v_sample.kind)::uuid;
        IF EXISTS (SELECT 1 FROM orders WHERE id=v_order) THEN CONTINUE; END IF;
        v_promotion := md5(v_sample.promotion_key)::uuid;
        SELECT pt.sku_id,pt.category_id INTO v_target_sku,v_target_category
        FROM promotion_targets pt WHERE pt.promotion_id=v_promotion ORDER BY pt.id LIMIT 1;
        v_qty := v_sample.quantity;
        SELECT s.id,s.sell_price,s.tax_rate INTO v_sku,v_price,v_rate
        FROM skus s JOIN products p ON p.id=s.product_id
        JOIN stock_entries se ON se.store_id=s.store_id AND se.sku_id=s.id
        WHERE s.store_id=v_store AND s.is_active AND se.qty_on_hand>=v_qty
          AND (v_target_sku IS NULL OR s.id=v_target_sku)
          AND (v_target_category IS NULL OR p.category_id=v_target_category)
          AND (v_sample.kind<>'CartFixed' OR s.sell_price*v_qty>=100000)
          AND EXISTS (SELECT 1 FROM stock_batches b WHERE b.store_id=s.store_id AND b.sku_id=s.id AND b.qty>=v_qty)
        ORDER BY s.sku_code LIMIT 1;
        IF v_sku IS NULL THEN RAISE EXCEPTION 'No stocked eligible SKU for promotion scenario %',v_sample.kind; END IF;

        v_gross := v_price*v_qty;
        v_discount := CASE v_sample.kind
            WHEN 'PercentSku' THEN round(v_gross*0.05,2)
            WHEN 'FixedSku' THEN least(v_gross,5000*v_qty)
            WHEN 'BuyXGetY' THEN v_price
            WHEN 'CartFixed' THEN least(v_gross,15000)
            WHEN 'HappyHour' THEN round(v_gross*0.10,2)
        END;
        SELECT value INTO v_rate FROM promotions WHERE id=v_promotion;
        IF v_sample.kind='HappyHour' THEN
            v_discount := round(v_gross*(v_rate/100),2);
        ELSIF v_sample.kind='PercentSku' THEN
            v_discount := round(v_gross*(v_rate/100),2);
        END IF;
        v_tax := round((v_gross-v_discount)*((SELECT tax_rate FROM skus WHERE id=v_sku)/100),2);
        v_total := v_gross-v_discount+v_tax;
        v_day := v_sample.sale_day;
        v_paid_at := ((v_day+CASE WHEN v_sample.kind='HappyHour' THEN time '15:30' ELSE time '12:00' END) AT TIME ZONE 'Asia/Ho_Chi_Minh');
        v_shift := md5('seed-shift:'||v_day::text||':1')::uuid;
        v_customer := CASE WHEN v_sample.customer_barcode IS NULL THEN NULL ELSE (SELECT id FROM customers WHERE barcode=v_sample.customer_barcode) END;
        v_voucher := CASE WHEN v_sample.voucher_code IS NULL THEN NULL ELSE (SELECT id FROM vouchers WHERE code=v_sample.voucher_code) END;

        INSERT INTO orders(id,store_id,shift_id,customer_id,status,currency_code,subtotal,discount_total,tax_total,grand_total,note,applied_voucher_id,applied_voucher_code,created_by,created_at,paid_at,cancel_reason)
        VALUES(v_order,v_store,v_shift,v_customer,'Paid','VND',v_gross,v_discount,v_tax,v_total,
               'Seed promotion example: '||v_sample.kind,v_voucher,v_sample.voucher_code,v_cashier,v_paid_at,v_paid_at,NULL);
        INSERT INTO order_items(id,order_id,sku_id,qty,unit_price,discount_amount,tax_amount,line_total)
        VALUES(md5('seed-promotion-example-item:'||v_sample.kind)::uuid,v_order,v_sku,v_qty,v_price,v_discount,v_tax,v_gross-v_discount+v_tax);
        INSERT INTO order_discounts(id,order_id,promotion_id,voucher_id,discount_amount,description,applied_at)
        VALUES(md5('seed-promotion-example-discount:'||v_sample.kind)::uuid,v_order,v_promotion,v_voucher,v_discount,
               CASE v_sample.kind WHEN 'BuyXGetY' THEN 'Mua 2 tặng 1' WHEN 'FixedSku' THEN 'Giảm cố định theo SKU' WHEN 'CartFixed' THEN 'Giảm cố định toàn đơn' WHEN 'HappyHour' THEN 'Khung giờ vàng 15:30' ELSE 'Giảm phần trăm theo SKU' END,v_paid_at);
        IF v_voucher IS NOT NULL THEN
            INSERT INTO voucher_usages(id,voucher_id,customer_id,order_id,used_at)
            VALUES(md5('seed-promotion-example-voucher-use:'||v_sample.kind)::uuid,v_voucher,v_customer,v_order,v_paid_at);
            UPDATE vouchers SET used_count=(SELECT count(*) FROM voucher_usages WHERE voucher_id=v_voucher) WHERE id=v_voucher;
        END IF;
        INSERT INTO payments(id,order_id,method,amount,change_amount,transaction_ref,merchant_reference,status,gateway_response_json,paid_at)
        VALUES(md5('seed-promotion-example-payment:'||v_sample.kind)::uuid,v_order,'Cash',v_total,NULL,NULL,NULL,'Success',NULL,v_paid_at);
        INSERT INTO stock_transactions(id,store_id,sku_id,type,qty,unit_cost,order_id,stock_in_voucher_id,note,created_by,created_at)
        SELECT md5('seed-promotion-example-stock-tx:'||v_sample.kind)::uuid,v_store,v_sku,'SaleOut',v_qty,s.cost_price,v_order,NULL,'Seed promotion scenario sale',v_cashier,v_paid_at
        FROM skus s WHERE s.id=v_sku;
        UPDATE stock_entries SET qty_on_hand=qty_on_hand-v_qty,last_updated=v_paid_at WHERE store_id=v_store AND sku_id=v_sku;
        UPDATE stock_batches SET qty=qty-v_qty WHERE id=(SELECT b.id FROM stock_batches b WHERE b.store_id=v_store AND b.sku_id=v_sku AND b.qty>=v_qty ORDER BY b.expiry_date NULLS LAST,b.received_at LIMIT 1);

        INSERT INTO invoice_sequences(store_id,invoice_date,last_value) VALUES(v_store,v_day,1)
        ON CONFLICT (store_id,invoice_date) DO UPDATE SET last_value=invoice_sequences.last_value+1
        RETURNING last_value INTO v_invoice_sequence;
        SELECT 'HD-'||code||'-'||to_char(v_day,'YYYYMMDD')||'-'||lpad(v_invoice_sequence::text,6,'0') INTO v_invoice_no FROM stores WHERE id=v_store;
        INSERT INTO invoices(id,order_id,invoice_no,buyer_name,buyer_tax_code,buyer_address,total_before_tax,tax_amount,grand_total,issued_at)
        VALUES(md5('seed-promotion-example-invoice:'||v_sample.kind)::uuid,v_order,v_invoice_no,
               (SELECT name FROM customers WHERE id=v_customer),NULL,NULL,v_gross-v_discount,v_tax,v_total,v_paid_at);

        IF v_customer IS NOT NULL THEN
            UPDATE customers SET total_spending=total_spending+v_total,
                member_tier_id=CASE WHEN total_spending+v_total>=30000000 THEN v_vip WHEN total_spending+v_total>=15000000 THEN v_gold WHEN total_spending+v_total>=5000000 THEN v_silver ELSE v_normal END
            WHERE id=v_customer;
            SELECT mt.point_rate INTO v_rate FROM customers c JOIN member_tiers mt ON mt.id=c.member_tier_id WHERE c.id=v_customer;
            INSERT INTO point_transactions(id,customer_id,order_id,type,points,note,created_at)
            VALUES(md5('seed-promotion-example-points:'||v_sample.kind)::uuid,v_customer,v_order,'Earn',round(v_total*COALESCE(v_rate,0.01),0),'Điểm từ đơn hàng khuyến mãi',v_paid_at);
            UPDATE loyalty_accounts SET points_balance=(SELECT COALESCE(sum(CASE WHEN type='Redeem' THEN -points ELSE points END),0) FROM point_transactions WHERE customer_id=v_customer),last_updated=v_paid_at
            WHERE customer_id=v_customer;
        END IF;
    END LOOP;
END;
$promotion_seed$;

COMMIT;

-- Relationship / integrity smoke checks for all operational seed groups.
SELECT 'seed_orders' AS check_name, count(*) AS rows FROM orders WHERE created_at >= '2026-09-01+07' AND created_at < '2027-01-01+07'
UNION ALL SELECT 'seed_invoices', count(*) FROM invoices WHERE issued_at >= '2026-09-01+07' AND issued_at < '2027-01-01+07'
UNION ALL SELECT 'seed_payments', count(*) FROM payments WHERE paid_at >= '2026-09-01+07' AND paid_at < '2027-01-01+07'
UNION ALL SELECT 'seed_stock_receipts', count(*) FROM stock_in_vouchers WHERE created_at >= '2026-09-01+07' AND created_at < '2027-01-01+07'
UNION ALL SELECT 'seed_stock_transactions', count(*) FROM stock_transactions WHERE created_at >= '2026-09-01+07' AND created_at < '2027-01-01+07';
